def equation(eps, T, params):
    p=params
    return p[0]+p[1]*T+p[2]*T**2+p[3]*eps*T**2+p[4]*eps**p[5]*np.exp(-p[6]*eps/T)+p[7]*np.exp(-p[8]*eps)+p[9]*T*np.exp(-p[8]*eps)

def fitbasis(cols):
    A=np.array(cols).T
